"получается 100: 4 · 23 · 25 = 2 300; 25 · 31 · 4 = 3 100": "100 шығады: 4 · 23 · 25 = 2 300; 25 · 31 · 4 = 3 100",
"Найди первое неполное делимое и посчитай цифры частного.": "Бірінші толымсыз бөлінгішті тауып, бөліндінің цифрларын сана.",
