"нуль в конце частного: 1 400 : 14 = 100; 3 500 : 35 = 100": "бөліндінің соңындағы нөл: 1 400 : 14 = 100; 3 500 : 35 = 100",
"Если ответ сильно отличается от прикидки, считаем заново.": "Жауап болжаудан қатты ерекшеленсе, қайта есептейміз.",
