"старт из разных мест, в начале есть расстояние между ними": "әртүрлі жерден жолға шығу, басында арақашықтық бар",
"В произведении 147 · 2 000 пишем 294 и приписываем 3 нуля.": "147 · 2 000 көбейтіндісінде 294 жазып, 3 нөл жалғаймыз.",
"нуль в частном: 107 642 : 214 = 503; 375 500 : 125 = 3 004": "бөліндідегі нөл: 107 642 : 214 = 503; 375 500 : 125 = 3 004",
