"Объекты выезжают одновременно и встречаются в один момент.": "Нысандар бір мезгілде шығып, бір сәтте кездеседі.",
"Трое поваров лепили по 3, 4 и 5 часов, всего 240 пельменей": "Үш аспаз 3, 4 және 5 сағат бойы жасады, барлығы 240 тоқаш",
