"Сколько разных остатков может получиться при делении на 12?": "12-ге бөлгенде неше түрлі қалдық шығуы мүмкін?",
"Кулинар печёт 25 кексов в час. За сколько часов 100 кексов?": "Аспаз сағатына 25 кекс пісіреді. 100 кекс неше сағатта?",
