"В записи 1 764 : 42 первое неполное делимое — 176.": "1 764 : 42 жазбасында бірінші толымсыз бөлінгіш — 176.",
"Частное умножаем на делитель и прибавляем остаток.": "Бөлінділі бөлгішке көбейтіп, қалдықты қосамыз.",
"вместе 8: 5 кг и 3 кг: всего 8; 2 м и 6 м: всего 8": "бірге 8: 5 кг және 3 кг: барлығы 8; 2 м және 6 м: барлығы 8",
"Скорость сближения считают, пока едет один объект.": "Жақындау жылдамдығын тек бір нысан жүріп тұрғанда санайды.",
"Неверно: 150 : (9 − 6) = 50 (тенге), а не 150 : 6.": "Бұрыс: 150 : (9 − 6) = 50 (теңге), ал 150 : 6 емес.",
"Неверно: сотни делим на сотни, получается просто 4.": "Бұрыс: жүздікті жүздікке бөлеміз, жай ғана 4 шығады.",
"произведение больше делимого, цифра слишком большая": "көбейтінді бөлінгіштен үлкен, цифр тым үлкен",
"234 · 5 = 1 170 и 234 · 300 = 70 200. Сумма 71 370.": "234 · 5 = 1 170 және 234 · 300 = 70 200. Қосынды 71 370.",
"Формулы устанавливают взаимосвязь между величинами.": "Формулалар шамалар арасындағы байланысты көрсетеді.",
"разность количества разделить на разность стоимости": "сан айырмасын құн айырмасына бөлу",
"Скорость удаления бывает меньше любой из скоростей.": "Алыстау жылдамдығы жылдамдықтардың кез келгенінен кіші болуы мүмкін.",
"Урок 8. Деление на двузначное число: нуль в частном": "8-сабақ. Екі таңбалы санға бөлу: бөліндідегі нөл",
"Нули отбрасываем поровну: 548 100 : 90 = 54 810 : 9.": "Нөлдерді тең алып тастаймыз: 548 100 : 90 = 54 810 : 9.",
"Если остаток равен 0, деление выполнено без остатка.": "Қалдық 0-ге тең болса, бөлу қалдықсыз орындалған.",
