"Делитель умножаем на частное и прибавляем остаток.": "Бөлгішті бөліндіге көбейтіп, қалдықты қосамыз.",
"Прикинь результат и выбери верный ответ: 198 · 51.": "Нәтижені болжап, дұрыс жауапты таңда: 198 · 51.",
