"v совм. = 40 + 25 = 65 вёдер в час. A = 65 · 4 = 260.": "v бірг. = 40 + 25 = 65 шелек/сағ. A = 65 · 4 = 260.",
"Неверно: второй ехал на 1 ч меньше, 18 · 3 = 54 (км).": "Бұрыс: екіншісі 1 сағат аз жүрді, 18 · 3 = 54 (км).",
"Пекарня выпекает 80 лепёшек в час. Когда будет 1 200?": "Наубайхана сағатына 80 нан пісіреді. 1 200 қашан болады?",
