"В записи 624 : 78 число 624 — делимое, а 78 — делитель.": "624 : 78 жазбасында 624 саны — бөлінгіш, ал 78 — бөлгіш.",
"Какое первое неполное делимое при делении 66 882 : 213?": "66 882 : 213 бөлгенде бірінші толымсыз бөлінгіш қандай?",
