"Частное 503. Нуль тоже цифра частного, поэтому цифр три.": "Бөлінді 503. Нөл де бөліндінің цифры, сондықтан цифр үшеу.",
"Вместе 12 + 8 = 20 открыток в час. За 5 ч: 20 · 5 = 100.": "Бірге 12 + 8 = 20 открытка/сағ. 5 сағатта: 20 · 5 = 100.",
"Неверно: разность стоимости делят на разность количеств.": "Бұрыс: құн айырмасын сан айырмасына бөледі.",
"В частном 4 800 : 60 столько же нулей, сколько в делимом.": "4 800 : 60 бөліндісінде бөлінгіштегідей нөл бар.",
"Чтобы найти цену, надо стоимость разделить на количество.": "Бағаны табу үшін құнды санға бөлу керек.",
"удобно умножить: 25 · 17 · 4 = 1 700; 125 · 9 · 8 = 9 000": "ыңғайлы көбейту: 25 · 17 · 4 = 1 700; 125 · 9 · 8 = 9 000",
