"Второе неполное произведение начинаем писать под десятками.": "Екінші толымсыз көбейтіндіні ондықтың астынан бастап жазамыз.",
"v = 30 : 5 = 6 дет./мин. В часе 60 минут: 6 · 60 = 360 дет.": "v = 30 : 5 = 6 бөлшек/мин. Бір сағатта 60 минут: 6 · 60 = 360 бөлшек.",
"Единицей в задаче может быть 1 час, 1 килограмм или 1 метр.": "Есепте бірлік ретінде 1 сағат, 1 килограмм немесе 1 метр болуы мүмкін.",
"сумма скоростей от 100 до 150: 60 + 50 = 110; 72 + 68 = 140": "жылдамдықтар қосындысы 100-ден 150-ге дейін: 60 + 50 = 110; 72 + 68 = 140",
