"Неверно: 1 960 : 7 = 280. Нуль в конце частного терять нельзя.": "Бұрыс: 1 960 : 7 = 280. Бөліндінің соңындағы нөлді жоғалтуға болмайды.",
"Время равно работе, делённой на производительность: t = A : v.": "Уақыт жұмысты өнімділікке бөлгенге тең: t = A : v.",
"При одной производительности работа растёт вместе со временем.": "Өнімділік бірдей болғанда, жұмыс уақытпен бірге артады.",
