"6 цифр в произведении: 512 · 314 = 160 768; 999 · 101 = 100 899": "көбейтіндіде 6 цифр: 512 · 314 = 160 768; 999 · 101 = 100 899",
"1) 3 + 5 = 8 (кг) — всего. 2) 2 400 : 8 = 300 (тг) — цена 1 кг.": "1) 3 + 5 = 8 (кг) — барлығы. 2) 2 400 : 8 = 300 (тг) — 1 кг бағасы.",
"Скорости 40 и 50 км/ч. Сколько километров между ними через 2 ч?": "Жылдамдықтары 40 және 50 км/сағ. 2 сағаттан кейін олардың арасы неше шақырым?",
